-- descripcion
INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (346, 'descripcion', 'generic', '{"text": "Se convoca a todos los Asociados del club de golf Valle Alto e invitados a participar en su LXX Torneo Anual de Invitación, que se llevará a cabo del 24 de abril al 02 de mayo de 2026 en las instalaciones de nuestro club.\\n\\nBases: Podrán participar damas y caballeros amateurs mayores de 18 años con hándicap registrado en la FMG o en el sistema interno del club publicado al 1° de abril de 2026. En categoría “Campeonato y Premier” se permitirá jugar a menores de 18 años que cuenten con el hándicap solicitado. Al jugador que no tenga hándicap registrado, los profesionales podrán calcularle uno siempre y cuando tenga un mínimo de 8 scores entregados.\\n\\n#TORNEOANUAL70"}', 1, 1)
ON DUPLICATE KEY UPDATE
  section_type = 'generic',
  content = '{"text": "Se convoca a todos los Asociados del club de golf Valle Alto e invitados a participar en su LXX Torneo Anual de Invitación, que se llevará a cabo del 24 de abril al 02 de mayo de 2026 en las instalaciones de nuestro club.\\n\\nBases: Podrán participar damas y caballeros amateurs mayores de 18 años con hándicap registrado en la FMG o en el sistema interno del club publicado al 1° de abril de 2026. En categoría “Campeonato y Premier” se permitirá jugar a menores de 18 años que cuenten con el hándicap solicitado. Al jugador que no tenga hándicap registrado, los profesionales podrán calcularle uno siempre y cuando tenga un mínimo de 8 scores entregados.\\n\\n#TORNEOANUAL70"}',
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

-- elegibilidad
INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (346, 'elegibilidad', 'generic', '{"eligibilityText": "Podrán participar damas y caballeros amateurs mayores de 18 años con hándicap registrado en la FMG o en el sistema interno del Club, publicado al 1° de abril de 2026. En categoría “Campeonato y Premier” se permite jugar a menores de 18 años que cuenten con el hándicap solicitado.", "notesText": ["La fecha límite de inscripción será el domingo 19 de abril, o al completar el cupo límite de cada categoría.", "La fecha límite para recibir cancelaciones será el martes 21 de abril. Después de esta fecha no se aceptan cancelaciones; las recibidas a tiempo serán reembolsadas.", "Los jugadores que soliciten participar en una categoría que no les corresponda por su hándicap tendrán que esperar hasta 2 días antes del inicio de juego de la categoría solicitada, para asegurar que no quede fuera otro jugador que sí cumpla con el hándicap requerido.", "Al jugador sin hándicap registrado, los profesionales podrán calcularle uno siempre y cuando tenga un mínimo de 8 scores entregados."], "inscripcionesText": "Asociados: a partir del miércoles 01 de abril.\\nHijos de socios dependientes: a partir del miércoles 15 de abril.\\nInvitados e hijos no dependientes: a partir del domingo 19 de abril."}', 1, 2)
ON DUPLICATE KEY UPDATE
  section_type = 'generic',
  content = '{"eligibilityText": "Podrán participar damas y caballeros amateurs mayores de 18 años con hándicap registrado en la FMG o en el sistema interno del Club, publicado al 1° de abril de 2026. En categoría “Campeonato y Premier” se permite jugar a menores de 18 años que cuenten con el hándicap solicitado.", "notesText": ["La fecha límite de inscripción será el domingo 19 de abril, o al completar el cupo límite de cada categoría.", "La fecha límite para recibir cancelaciones será el martes 21 de abril. Después de esta fecha no se aceptan cancelaciones; las recibidas a tiempo serán reembolsadas.", "Los jugadores que soliciten participar en una categoría que no les corresponda por su hándicap tendrán que esperar hasta 2 días antes del inicio de juego de la categoría solicitada, para asegurar que no quede fuera otro jugador que sí cumpla con el hándicap requerido.", "Al jugador sin hándicap registrado, los profesionales podrán calcularle uno siempre y cuando tenga un mínimo de 8 scores entregados."], "inscripcionesText": "Asociados: a partir del miércoles 01 de abril.\\nHijos de socios dependientes: a partir del miércoles 15 de abril.\\nInvitados e hijos no dependientes: a partir del domingo 19 de abril."}',
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

