INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (346, 'costos', 'generic', '{"sociosPricing": [{"title": "Costo de Inscripción", "subtitle": "Cuotas aplicables únicamente para jugadores que participen en el Torneo.", "tiers": [{"categoria": "Socios Titulares", "costo": "$6,000.00"}, {"categoria": "Eméritos", "costo": "$5,000.00"}, {"categoria": "Damas", "costo": "$5,000.00"}, {"categoria": "Dependientes", "costo": "$5,000.00"}, {"categoria": "Invitados Caballeros", "costo": "$18,500.00"}, {"categoria": "Invitados Damas y Juveniles", "costo": "$10,500.00"}]}], "foraneosPricing": [], "pricingNote": "Las inscripciones se abren por etapas: Asociados a partir del 01 de abril, hijos de socios dependientes a partir del 15 de abril, e invitados e hijos no dependientes a partir del 19 de abril. La fecha límite de inscripción es el domingo 19 de abril o al completar el cupo de cada categoría.", "contactInfo": {"bankName": "", "clabe": "", "cuenta": "", "nombre": "Club de Golf Valle Alto", "email": "", "telefono": "", "telefonoDirecto": ""}, "contactWarning": "", "inscripcionesText": "Asociados: a partir del miércoles 01 de abril.\\nHijos de socios dependientes: a partir del miércoles 15 de abril.\\nInvitados e hijos no dependientes: a partir del domingo 19 de abril."}', 1, 3)
