INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (346, 'competencias', 'list', '{"items": [{"nombre": "Tiro Espectacular de Approach", "descripcion": "Podrán participar únicamente jugadores inscritos al torneo. Cada participante tendrá derecho a 2 tiros en los días de calificación; pasan a la final los mejores 10 resultados diarios. Calificación: sábado 25, domingo 26, lunes 27 y martes 28 de abril, en el área del par 3, de 11:00 a 17:00 hrs. La final se jugará el miércoles 29 de abril a partir de las 18:30 hrs. en el Green del Hoyo 15 (presentarse 15 min antes en la terraza del Kiosco 10). El turno de los finalistas será en orden de menor a mayor distancia marcada en calificación.", "premios": "1° Lugar: Auto 2026 (solo se entrega un auto). 2° Lugar: Bolsa de Golf."}, {"nombre": "Torneo de Putt", "descripcion": "Calificación diaria del sábado 25 al miércoles 29 de abril en el área del Putting Green, 11:00 a 17:00 hrs. Cada jugador tendrá 2 tiros (sólo puede participar 1 vez por día). Pasan a la final los mejores 64 caballeros (14 por día sáb-lun, 11 por día mar-mié) y las mejores 32 damas (7 por día sáb-mar, 4 el miércoles). En caso de empate gana el primer jugador que participó. Final el viernes 1 de mayo: 18:00 hrs. damas, 19:30 hrs. caballeros.", "premios": "Damas y Caballeros — 1° Lugar: $10,000 en Vales Back 9 · 2° Lugar: $7,000 en Vales Back 9 · 3° Lugar: $5,000 en Vales Back 9."}, {"nombre": "Tiro Espectacular de Putt (35 yds)", "descripcion": "Participan las 4 finalistas del Torneo de Putt damas y los 8 finalistas del Torneo de Putt caballeros. Se juega el viernes 1 de mayo durante el Torneo de Putt una vez que se tengan los finalistas. 1 putt de 35 yardas en el Putting Green de la Terraza, con sorteo previo para definir turno; un solo tiro por participante.", "premios": "Primer jugador que la emboque: $25,000 USD. Segundo que la emboque o mejor O´yes: Bolsa de Golf."}, {"nombre": "Torneo Driver Damas", "descripcion": "Día de juego: lunes 27 de abril (1ª ronda), en el Hoyo 4. Driver de distancia: se premia el driver más largo (que caiga dentro del fairway del hoyo 4) entre las categorías A, B, C, D y E. Driver de precisión: se premia la pelota más cerca de la línea marcada en el fairway del hoyo 4 entre A, B, C, D, E y Estelares. Una jugadora no podrá ganar ambos premios. Desempates: distancia se decide por la bola más cercana a la línea; precisión se decide por la bola con mayor distancia.", "premios": "1° Lugar de Distancia: 300 USD · 1° Lugar de Precisión: 300 USD."}, {"nombre": "Torneo Driver Caballeros", "descripcion": "Podrán participar todos los jugadores inscritos al torneo con un mínimo de 280 yardas de distancia. Inscripciones el día del evento en la mesa de salida del Hoyo 16. Habrá una sola categoría; cada jugador tendrá 2 tiros y se medirá el más largo que caiga dentro del fairway. Día: jueves 30 de abril a las 18:30 hrs. en el tee del Hoyo 16. Desempate: 2 tiros adicionales en fairway; el ganador final tendrá 2 tiros más para intentar mejorar su distancia.", "premios": "1° Lugar: 400 USD · 2° Lugar: 300 USD."}, {"nombre": "Premios O´yes", "descripcion": "Mejor O´yes general del día: Driver Ping modelo G440 y Putter Scotty Cameron. Mejor O´yes de cada par 3 del día: premio por hoyo. Mejor O´yes general del torneo: Certificado de Regalo Back9 por $50,000 MXN.", "premios": "Driver Ping G440 + Putter Scotty Cameron + Certificado Back9 $50,000 MXN."}]}', 1, 5)
ON DUPLICATE KEY UPDATE
  section_type = 'list',
  content = '{"items": [{"nombre": "Tiro Espectacular de Approach", "descripcion": "Podrán participar únicamente jugadores inscritos al torneo. Cada participante tendrá derecho a 2 tiros en los días de calificación; pasan a la final los mejores 10 resultados diarios. Calificación: sábado 25, domingo 26, lunes 27 y martes 28 de abril, en el área del par 3, de 11:00 a 17:00 hrs. La final se jugará el miércoles 29 de abril a partir de las 18:30 hrs. en el Green del Hoyo 15 (presentarse 15 min antes en la terraza del Kiosco 10). El turno de los finalistas será en orden de menor a mayor distancia marcada en calificación.", "premios": "1° Lugar: Auto 2026 (solo se entrega un auto). 2° Lugar: Bolsa de Golf."}, {"nombre": "Torneo de Putt", "descripcion": "Calificación diaria del sábado 25 al miércoles 29 de abril en el área del Putting Green, 11:00 a 17:00 hrs. Cada jugador tendrá 2 tiros (sólo puede participar 1 vez por día). Pasan a la final los mejores 64 caballeros (14 por día sáb-lun, 11 por día mar-mié) y las mejores 32 damas (7 por día sáb-mar, 4 el miércoles). En caso de empate gana el primer jugador que participó. Final el viernes 1 de mayo: 18:00 hrs. damas, 19:30 hrs. caballeros.", "premios": "Damas y Caballeros — 1° Lugar: $10,000 en Vales Back 9 · 2° Lugar: $7,000 en Vales Back 9 · 3° Lugar: $5,000 en Vales Back 9."}, {"nombre": "Tiro Espectacular de Putt (35 yds)", "descripcion": "Participan las 4 finalistas del Torneo de Putt damas y los 8 finalistas del Torneo de Putt caballeros. Se juega el viernes 1 de mayo durante el Torneo de Putt una vez que se tengan los finalistas. 1 putt de 35 yardas en el Putting Green de la Terraza, con sorteo previo para definir turno; un solo tiro por participante.", "premios": "Primer jugador que la emboque: $25,000 USD. Segundo que la emboque o mejor O´yes: Bolsa de Golf."}, {"nombre": "Torneo Driver Damas", "descripcion": "Día de juego: lunes 27 de abril (1ª ronda), en el Hoyo 4. Driver de distancia: se premia el driver más largo (que caiga dentro del fairway del hoyo 4) entre las categorías A, B, C, D y E. Driver de precisión: se premia la pelota más cerca de la línea marcada en el fairway del hoyo 4 entre A, B, C, D, E y Estelares. Una jugadora no podrá ganar ambos premios. Desempates: distancia se decide por la bola más cercana a la línea; precisión se decide por la bola con mayor distancia.", "premios": "1° Lugar de Distancia: 300 USD · 1° Lugar de Precisión: 300 USD."}, {"nombre": "Torneo Driver Caballeros", "descripcion": "Podrán participar todos los jugadores inscritos al torneo con un mínimo de 280 yardas de distancia. Inscripciones el día del evento en la mesa de salida del Hoyo 16. Habrá una sola categoría; cada jugador tendrá 2 tiros y se medirá el más largo que caiga dentro del fairway. Día: jueves 30 de abril a las 18:30 hrs. en el tee del Hoyo 16. Desempate: 2 tiros adicionales en fairway; el ganador final tendrá 2 tiros más para intentar mejorar su distancia.", "premios": "1° Lugar: 400 USD · 2° Lugar: 300 USD."}, {"nombre": "Premios O´yes", "descripcion": "Mejor O´yes general del día: Driver Ping modelo G440 y Putter Scotty Cameron. Mejor O´yes de cada par 3 del día: premio por hoyo. Mejor O´yes general del torneo: Certificado de Regalo Back9 por $50,000 MXN.", "premios": "Driver Ping G440 + Putter Scotty Cameron + Certificado Back9 $50,000 MXN."}]}',
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

